const e={aapl:{canonical:"aapl",category:"crown",endState:{cn:"苹果",tw:"蘋果",en:"Apple",ja:"アップル",es:"Apple",ko:"애플",fr:"Apple",de:"Apple"},line:{cn:"iPhone + Services 现金机器,2024 年再度登顶。",tw:"iPhone + Services 現金機器,2024 年再度登頂。",en:"Still the iPhone-plus-services cash machine; retook #1 in 2024.",ja:"iPhone とサービスの現金製造機は健在。2024 年に首位を奪還した。",es:"Sigue siendo la máquina de caja del iPhone más servicios; recuperó el primer puesto en 2024.",ko:"아이폰과 서비스가 만들어내는 현금 기계는 여전하다. 2024년 다시 1위를 되찾았다.",fr:"Toujours la machine à cash iPhone + services ; a repris la première place en 2024.",de:"Weiterhin die Cash-Maschine aus iPhone und Diensten; 2024 zurück auf Platz eins."}},msft:{canonical:"msft",category:"crown",endState:{cn:"微软",tw:"微軟",en:"Microsoft",ja:"マイクロソフト",es:"Microsoft",ko:"마이크로소프트",fr:"Microsoft",de:"Microsoft"},line:{cn:"Azure + Copilot 的二次再估值,把 1999 的桌面巨头改写成 AI 时代的云股。",tw:"Azure + Copilot 的二次再估值,把 1999 的桌面巨頭改寫成 AI 時代的雲股。",en:"Re-rated as the AI-cycle cloud platform; the 1999 desktop monopoly rewritten as Azure + Copilot.",ja:"AI サイクルのクラウド基盤として再評価され、1999 年のデスクトップ独占は Azure と Copilot に書き換えられた。",es:"Revalorada como la plataforma cloud del ciclo de la IA: el monopolio de escritorio de 1999 reescrito en Azure y Copilot.",ko:"AI 사이클의 클라우드 플랫폼으로 재평가됐다. 1999년의 데스크톱 독점이 애저와 코파일럿으로 다시 쓰였다.",fr:"Revalorisée en plateforme cloud du cycle IA ; le monopole du bureau de 1999 réécrit en Azure et Copilot.",de:"Als Cloud-Plattform des KI-Zyklus neu bewertet; das Desktop-Monopol von 1999 wurde zu Azure und Copilot umgeschrieben."}},googl:{canonical:"googl",category:"crown",endState:{cn:"Alphabet",tw:"Alphabet",en:"Alphabet",ja:"アルファベット",es:"Alphabet",ko:"알파벳",fr:"Alphabet",de:"Alphabet"},line:{cn:"搜索 + 数字广告仍是利润引擎,Gemini / Waymo 是看涨期权。",tw:"搜尋 + 數位廣告仍是利潤引擎,Gemini / Waymo 是看漲期權。",en:"Search-and-ads remains the profit engine; Gemini and Waymo carry the upside option.",ja:"検索と広告が依然として利益エンジンであり、Gemini と Waymo が上振れのオプションを担う。",es:"La búsqueda y la publicidad siguen siendo el motor de beneficios; Gemini y Waymo son la opción alcista.",ko:"검색과 광고가 여전히 이익 엔진이고, 제미나이와 웨이모가 상승 옵션을 맡는다.",fr:"La recherche et la publicité restent le moteur de profit ; Gemini et Waymo portent l'option de hausse.",de:"Suche und Werbung bleiben der Gewinnmotor; Gemini und Waymo tragen die Aufwärtsoption."}},brk:{canonical:"brk",category:"crown",endState:{cn:"伯克希尔·哈撒韦",tw:"波克夏·海瑟威",en:"Berkshire Hathaway",ja:"バークシャー・ハサウェイ",es:"Berkshire Hathaway",ko:"버크셔 해서웨이",fr:"Berkshire Hathaway",de:"Berkshire Hathaway"},line:{cn:"保险 + 投资 + 实业混合体,Buffett 60 年复利的现在式。",tw:"保險 + 投資 + 實業混合體,Buffett 60 年複利的現在式。",en:"An insurance + investing + operating-holdings composite — Buffett's six-decade compounder in its present tense.",ja:"保険と投資と事業会社の複合体——バフェットの六十年にわたる複利の現在形である。",es:"Un compuesto de seguros, inversión y filiales operativas: el interés compuesto de seis décadas de Buffett en presente.",ko:"보험과 투자, 사업회사가 뒤섞인 복합체 — 버핏이 60년 굴린 복리의 현재형이다.",fr:"Un composite d'assurance, d'investissement et de filiales industrielles — la capitalisation de six décennies de Buffett au présent.",de:"Ein Verbund aus Versicherung, Beteiligungen und Industrieholdings — Buffetts sechs Jahrzehnte Zinseszins in der Gegenwartsform."}},att:{canonical:"att",category:"split",exitYear:1984,endState:{cn:"AT&T(SBC 反向收购后的电信运营商)",tw:"AT&T(SBC 反向收購後的電信業者)",en:"AT&T (the telco that emerged from SBC's reverse acquisition)",ja:"AT&T（SBC による逆買収から生まれた通信会社）",es:"AT&T (la teleco surgida de la adquisición inversa de SBC)",ko:"AT&T(SBC의 역인수에서 태어난 통신사)",fr:"AT&T (l'opérateur né de l'acquisition inversée par SBC)",de:"AT&T (der Telekomkonzern aus der umgekehrten Übernahme durch SBC)"},line:{cn:"1984 司法部反垄断拆为七家「小贝尔」,2005 由 SBC 反向收购沿用 AT&T 名字。",tw:"1984 司法部反壟斷拆為七家「小貝爾」,2005 由 SBC 反向收購沿用 AT&T 名字。",en:"Broken up by antitrust in 1984 into seven 'Baby Bells'; SBC reverse-acquired the AT&T name in 2005.",ja:"1984 年の反トラスト訴訟で七つの「ベビーベル」に分割され、2005 年に SBC が逆買収して AT&T の名を引き継いだ。",es:"Desmembrada por el antimonopolio en 1984 en siete «Baby Bells»; SBC se hizo con el nombre AT&T mediante una adquisición inversa en 2005.",ko:"1984년 반독점 판결로 일곱 개 '베이비 벨'로 쪼개졌고, 2005년 SBC가 역인수해 AT&T라는 이름을 이어받았다.",fr:"Démantelée par l'antitrust en 1984 en sept « Baby Bells » ; SBC a repris le nom AT&T par acquisition inversée en 2005.",de:"1984 vom Kartellrecht in sieben „Baby Bells“ zerlegt; SBC übernahm den Namen AT&T 2005 im Wege einer umgekehrten Akquisition."}},ge:{canonical:"ge",category:"split",exitYear:2024,endState:{cn:"GE Aerospace · GE Vernova · GE HealthCare 三家上市公司",tw:"GE Aerospace · GE Vernova · GE HealthCare 三家上市公司",en:"GE Aerospace · GE Vernova · GE HealthCare (three listed companies)",ja:"GE Aerospace・GE Vernova・GE HealthCare の上場三社",es:"GE Aerospace · GE Vernova · GE HealthCare (tres compañías cotizadas)",ko:"GE 에어로스페이스 · GE 버노바 · GE 헬스케어 세 개 상장사",fr:"GE Aerospace · GE Vernova · GE HealthCare (trois sociétés cotées)",de:"GE Aerospace · GE Vernova · GE HealthCare (drei börsennotierte Gesellschaften)"},line:{cn:"2018 被踢出道琼斯,2024 完成三拆,GE Capital 留下的金融化阴影才算清算干净。",tw:"2018 被踢出道瓊,2024 完成三拆,GE Capital 留下的金融化陰影才算清算乾淨。",en:"Removed from the Dow in 2018; the three-way split completed in 2024 finally cleared the GE Capital overhang.",ja:"2018 年にダウから外され、2024 年に完了した三分割でようやく GE キャピタルが残した金融化の影を清算した。",es:"Expulsada del Dow en 2018; la escisión en tres, culminada en 2024, saldó por fin la sombra financiera de GE Capital.",ko:"2018년 다우지수에서 퇴출됐고, 2024년 마무리된 3분할로 GE 캐피털이 남긴 금융화의 그림자를 비로소 청산했다.",fr:"Sortie du Dow en 2018 ; la scission en trois, achevée en 2024, a enfin soldé l'ombre financière de GE Capital.",de:"2018 aus dem Dow entfernt; die 2024 abgeschlossene Dreiteilung räumte endlich den Schatten von GE Capital ab."}},ibm:{canonical:"ibm",category:"listed",endState:{cn:"IBM(企业 IT 服务 + 混合云 + 量子)",tw:"IBM(企業 IT 服務 + 混合雲 + 量子)",en:"IBM (enterprise IT services + hybrid cloud + quantum)",ja:"IBM（企業向け IT サービス＋ハイブリッドクラウド＋量子）",es:"IBM (servicios TI para empresas + nube híbrida + cuántica)",ko:"IBM(기업용 IT 서비스 + 하이브리드 클라우드 + 양자)",fr:"IBM (services IT aux entreprises + cloud hybride + quantique)",de:"IBM (Unternehmens-IT-Dienste + Hybrid Cloud + Quantencomputing)"},line:{cn:"1990s 错过 PC,2000s 错过云,但靠 Red Hat 收购、Watson 与混合云在 2020s 慢慢回血。",tw:"1990s 錯過 PC,2000s 錯過雲,但靠 Red Hat 收購、Watson 與混合雲在 2020s 慢慢回血。",en:"Missed PCs in the 1990s, missed cloud in the 2000s — the Red Hat acquisition + Watson + hybrid cloud are the slow rebuild of the 2020s.",ja:"1990 年代に PC を、2000 年代にクラウドを取り逃した。レッドハット買収と Watson、ハイブリッドクラウドが 2020 年代の緩やかな再建である。",es:"Perdió el PC en los noventa y la nube en los dos mil; la compra de Red Hat, Watson y la nube híbrida son la lenta reconstrucción de esta década.",ko:"1990년대엔 PC를, 2000년대엔 클라우드를 놓쳤다. 레드햇 인수와 왓슨, 하이브리드 클라우드가 2020년대의 더딘 재건이다.",fr:"A raté le PC dans les années 1990 et le cloud dans les années 2000 ; le rachat de Red Hat, Watson et le cloud hybride sont la lente reconstruction des années 2020.",de:"Verpasste in den 1990ern den PC und in den 2000ern die Cloud — der Red-Hat-Kauf, Watson und die Hybrid Cloud sind der langsame Wiederaufbau der 2020er."}},exxon:{canonical:"exxon",category:"listed",endState:{cn:"Exxon Mobil",tw:"Exxon Mobil",en:"Exxon Mobil",ja:"エクソンモービル",es:"Exxon Mobil",ko:"엑슨모빌",fr:"Exxon Mobil",de:"Exxon Mobil"},line:{cn:"标准石油 1911 拆出来的最大碎片,2010s 被科技股从市值第一推下,仍是美股最大能源公司。",tw:"標準石油 1911 拆出來的最大碎片,2010s 被科技股從市值第一推下,仍是美股最大能源公司。",en:"Largest splinter of Rockefeller's 1911 break-up; eclipsed by tech in the 2010s but still America's biggest energy major.",ja:"1911 年のスタンダード・オイル分割で生まれた最大の破片。2010 年代にハイテク株へ首位を譲ったが、なお米国最大のエネルギー会社である。",es:"El mayor fragmento del desmembramiento de Standard Oil en 1911; eclipsada por la tecnología en la década de 2010, sigue siendo la mayor energética de EE. UU.",ko:"1911년 스탠더드 오일 분할에서 떨어져 나온 가장 큰 조각. 2010년대에 기술주에 1위를 내줬지만 여전히 미국 최대 에너지 기업이다.",fr:"Le plus gros éclat du démantèlement de la Standard Oil en 1911 ; éclipsée par la tech dans les années 2010, elle reste la première énergéticienne américaine.",de:"Der größte Splitter aus der Zerschlagung von Standard Oil 1911; in den 2010ern von Tech verdrängt, aber weiter Amerikas größter Energiekonzern."}},gm:{canonical:"gm",category:"bankrupt",exitYear:2009,endState:{cn:"GM(2010 重新上市后的新 GM)",tw:"GM(2010 重新上市後的新 GM)",en:"GM (the post-bailout listing)",ja:"GM（救済後、2010 年に再上場した新生 GM）",es:"GM (la cotizada posterior al rescate)",ko:"GM(구제금융 이후 2010년 재상장한 새 GM)",fr:"GM (la cotation d'après-sauvetage)",de:"GM (die Notierung nach der Rettung)"},line:{cn:"2009 金融危机里破产,500 亿美元政府救助后改名 New GM 重新上市,2010s 在 EV 上慢半拍。",tw:"2009 金融危機裡破產,500 億美元政府救助後改名 New GM 重新上市,2010s 在 EV 上慢半拍。",en:"Bankrupt in the 2009 GFC; relisted as 'New GM' after a $50bn government rescue, half a step behind on EVs in the 2010s.",ja:"2009 年の金融危機で破綻。500 億ドルの政府救済を経て「新 GM」として再上場したが、2010 年代の EV では半歩出遅れた。",es:"Quebró en la crisis de 2009; volvió a cotizar como «New GM» tras un rescate público de 50.000 millones, medio paso por detrás en los eléctricos.",ko:"2009년 금융위기 때 파산했고, 500억 달러 규모의 정부 구제 뒤 '뉴 GM'으로 재상장했지만 2010년대 전기차에서는 반 박자 늦었다.",fr:"Faillite lors de la crise de 2009 ; recotée en « New GM » après un sauvetage public de 50 milliards, avec un demi-pas de retard sur l'électrique.",de:"In der Finanzkrise 2009 insolvent; nach einer Staatshilfe von 50 Milliarden Dollar als „New GM“ zurück an die Börse, bei E-Autos einen halben Schritt zu spät."}},walmart:{canonical:"walmart",category:"listed",endState:{cn:"Walmart(全美最大零售商 + 全渠道电商)",tw:"Walmart(全美最大零售商 + 全通路電商)",en:"Walmart (#1 U.S. retailer + omnichannel)",ja:"ウォルマート（全米最大の小売＋オムニチャネル）",es:"Walmart (primer minorista de EE. UU. + omnicanal)",ko:"월마트(미국 최대 소매업체 + 옴니채널)",fr:"Walmart (premier détaillant américain + omnicanal)",de:"Walmart (größter US-Einzelhändler + Omnichannel)"},line:{cn:"Sam Walton 的物流革命撑到今天,亚马逊冲击下转型电商 + Walmart+。",tw:"Sam Walton 的物流革命撐到今天,Amazon 衝擊下轉型電商 + Walmart+。",en:"Sam Walton's logistics revolution still on its feet — pivoted to e-commerce and Walmart+ under Amazon pressure.",ja:"サム・ウォルトンの物流革命はいまも立っている。アマゾンの圧力を受け、EC と Walmart+ へ舵を切った。",es:"La revolución logística de Sam Walton sigue en pie: giró hacia el comercio electrónico y Walmart+ bajo la presión de Amazon.",ko:"샘 월턴의 물류 혁명은 여전히 살아 있다. 아마존의 압박 속에 전자상거래와 월마트+로 방향을 틀었다.",fr:"La révolution logistique de Sam Walton tient toujours debout — virage vers l'e-commerce et Walmart+ sous la pression d'Amazon.",de:"Sam Waltons Logistikrevolution steht noch — unter dem Druck von Amazon Wende zu E-Commerce und Walmart+."}},dupont:{canonical:"dupont",category:"split",exitYear:2019,endState:{cn:"Dow · DuPont · Corteva 三家上市公司",tw:"Dow · DuPont · Corteva 三家上市公司",en:"Dow · DuPont · Corteva (three listed companies)",ja:"Dow・DuPont・Corteva の上場三社",es:"Dow · DuPont · Corteva (tres compañías cotizadas)",ko:"다우 · 듀폰 · 코르테바 세 개 상장사",fr:"Dow · DuPont · Corteva (trois sociétés cotées)",de:"Dow · DuPont · Corteva (drei börsennotierte Gesellschaften)"},line:{cn:"2017 与 Dow 合并为 DowDuPont,2019 又拆为三家——化工 + 材料 + 农业各走各的。",tw:"2017 與 Dow 合併為 DowDuPont,2019 又拆為三家——化工 + 材料 + 農業各走各的。",en:"Merged into DowDuPont in 2017, then split into three in 2019 — chemicals, materials, and agriculture going their separate ways.",ja:"2017 年に Dow と合併して DowDuPont となり、2019 年に再び三分割——化学・素材・農業がそれぞれの道を行く。",es:"Se fusionó con Dow en 2017 para formar DowDuPont y volvió a dividirse en tres en 2019: química, materiales y agricultura por caminos separados.",ko:"2017년 다우와 합병해 다우듀폰이 됐다가 2019년 다시 셋으로 쪼개졌다 — 화학과 소재, 농업이 각자의 길을 갔다.",fr:"Fusionnée avec Dow en 2017 pour former DowDuPont, puis rescindée en trois en 2019 — chimie, matériaux et agriculture chacun de son côté.",de:"2017 mit Dow zu DowDuPont fusioniert, 2019 wieder in drei Teile zerlegt — Chemie, Werkstoffe und Agrar gingen getrennte Wege."}},ussteel:{canonical:"ussteel",category:"acquired",exitYear:2023,endState:{cn:"Nippon Steel 子公司(2023 公告,待审批)",tw:"Nippon Steel 子公司(2023 公告,待審批)",en:"Pending subsidiary of Nippon Steel (2023 announcement)",ja:"日本製鉄の子会社となる予定（2023 年公表、認可待ち）",es:"Futura filial de Nippon Steel (anuncio de 2023, pendiente de aprobación)",ko:"닛폰스틸의 자회사 예정(2023년 발표, 승인 대기)",fr:"Future filiale de Nippon Steel (annonce de 2023, en attente d'approbation)",de:"Künftige Tochter von Nippon Steel (Ankündigung 2023, Genehmigung ausstehend)"},line:{cn:"Carnegie + Morgan 1901 撮合出的世界第一家 10 亿美元公司,122 年后被日本制铁收购。",tw:"Carnegie + Morgan 1901 撮合出的世界第一家 10 億美元公司,122 年後被日本製鐵收購。",en:"The Carnegie + Morgan creation of 1901 — the world's first billion-dollar company — now being acquired by Nippon Steel.",ja:"カーネギーとモルガンが 1901 年に仕立てた世界初の 10 億ドル企業が、122 年後に日本製鉄へ渡ろうとしている。",es:"La criatura de Carnegie y Morgan de 1901 —la primera compañía de mil millones de dólares del mundo— pasa ahora a manos de Nippon Steel.",ko:"카네기와 모건이 1901년에 빚어낸 세계 최초의 10억 달러 기업이 122년 만에 닛폰스틸로 넘어가고 있다.",fr:"La création de Carnegie et Morgan en 1901 — première société milliardaire au monde — passe aujourd'hui sous pavillon Nippon Steel.",de:"Die Schöpfung von Carnegie und Morgan aus dem Jahr 1901 — das erste Milliardenunternehmen der Welt — geht nun an Nippon Steel."}},sears:{canonical:"sears",category:"bankrupt",exitYear:2018,endState:{cn:"Sears Holdings(2018 破产,门店数只剩几十家)",tw:"Sears Holdings(2018 破產,門店數只剩幾十家)",en:"Sears Holdings (bankrupt 2018; reduced to a few dozen stores)",ja:"シアーズ・ホールディングス（2018 年に破綻、店舗は数十店を残すのみ）",es:"Sears Holdings (quebrada en 2018; reducida a unas pocas decenas de tiendas)",ko:"시어스 홀딩스(2018년 파산, 매장은 수십 곳만 남았다)",fr:"Sears Holdings (faillite en 2018 ; réduite à quelques dizaines de magasins)",de:"Sears Holdings (2018 insolvent; auf einige Dutzend Filialen geschrumpft)"},line:{cn:"邮购目录时代的「亚马逊」——被沃尔玛切走低端、亚马逊切走目录,2018 破产。",tw:"郵購目錄時代的「Amazon」——被沃爾瑪切走低端、Amazon 切走目錄,2018 破產。",en:"The 'Amazon of the catalog era' — Walmart took the low end, Amazon took the catalog; bankrupt in 2018.",ja:"通販カタログ時代の「アマゾン」——低価格帯をウォルマートに、カタログをアマゾンに奪われ、2018 年に破綻した。",es:"El «Amazon de la era del catálogo»: Walmart se llevó la gama baja y Amazon el catálogo; quebró en 2018.",ko:"카탈로그 시대의 '아마존' — 저가 시장은 월마트에, 카탈로그는 아마존에 빼앗기고 2018년 파산했다.",fr:"L'« Amazon de l'ère du catalogue » — Walmart a pris l'entrée de gamme, Amazon le catalogue ; faillite en 2018.",de:"Das „Amazon der Katalogära“ — Walmart nahm das untere Segment, Amazon den Katalog; 2018 insolvent."}},kodak:{canonical:"kodak",category:"bankrupt",exitYear:2012,endState:{cn:"Kodak(2013 出破产保护后的特种化学 / 印刷小公司)",tw:"Kodak(2013 出破產保護後的特種化學 / 印刷小公司)",en:"Kodak (the post-2013 specialty-chemicals / print remnant)",ja:"コダック（2013 年に再建を終えた特殊化学・印刷の小企業）",es:"Kodak (el resto de químicos especiales e impresión posterior a 2013)",ko:"코닥(2013년 회생 절차를 마친 특수화학·인쇄 소기업)",fr:"Kodak (le reliquat chimie de spécialité / impression d'après 2013)",de:"Kodak (der Rest aus Spezialchemie und Druck nach 2013)"},line:{cn:"1975 内部就造出数字相机原型却为了胶片利润迟迟不商业化——2012 破产,商学院教材级失败。",tw:"1975 內部就造出數位相機原型卻為了膠片利潤遲遲不商業化——2012 破產,商學院教材級失敗。",en:"Built the first digital-camera prototype in-house in 1975 but stalled commercialisation to protect film margins — bankrupt in 2012, the textbook incumbent collapse.",ja:"1975 年に社内でデジタルカメラの試作機を作りながら、フィルムの利益を守るため商用化を先送りした——2012 年に破綻、教科書どおりの既存企業の崩壊である。",es:"Construyó el primer prototipo de cámara digital en 1975 pero frenó su comercialización para proteger el margen del carrete: quebró en 2012, el manual del incumbente que se hunde.",ko:"1975년 사내에서 디지털카메라 시제품을 만들고도 필름 마진을 지키려 상용화를 미뤘다 — 2012년 파산, 교과서에 실릴 만한 기존 강자의 붕괴다.",fr:"A construit le premier prototype d'appareil photo numérique en interne en 1975, puis freiné sa commercialisation pour protéger les marges de la pellicule — faillite en 2012, l'effondrement d'école.",de:"Baute 1975 im eigenen Haus den ersten Digitalkamera-Prototyp, verzögerte die Vermarktung aber zum Schutz der Filmmargen — 2012 insolvent, der Lehrbuchfall des gestürzten Platzhirschs."}},socal:{canonical:"socal",category:"acquired",exitYear:1984,endState:{cn:"Chevron(2001 与 Texaco 再合并)",tw:"Chevron(2001 與 Texaco 再合併)",en:"Chevron (which absorbed Texaco in 2001)",ja:"シェブロン（2001 年にテキサコを吸収）",es:"Chevron (que absorbió a Texaco en 2001)",ko:"셰브런(2001년 텍사코를 흡수)",fr:"Chevron (qui a absorbé Texaco en 2001)",de:"Chevron (2001 mit Texaco verschmolzen)"},line:{cn:"标准石油的另一块大碎片——加州标准石油 1984 更名 Chevron,后吞并 Texaco / Gulf。",tw:"標準石油的另一塊大碎片——加州標準石油 1984 更名 Chevron,後吞併 Texaco / Gulf。",en:"Another Standard Oil splinter — renamed Chevron in 1984, later absorbed Texaco and Gulf.",ja:"スタンダード・オイルのもう一つの大きな破片——カリフォルニア・スタンダードは 1984 年にシェブロンへ改称し、のちにテキサコとガルフを呑み込んだ。",es:"Otro gran fragmento de Standard Oil: la Standard de California pasó a llamarse Chevron en 1984 y luego absorbió a Texaco y Gulf.",ko:"스탠더드 오일의 또 다른 큰 조각 — 캘리포니아 스탠더드는 1984년 셰브런으로 이름을 바꾸고 이후 텍사코와 걸프를 삼켰다.",fr:"Un autre grand éclat de la Standard Oil — la Standard de Californie devient Chevron en 1984, avant d'absorber Texaco et Gulf.",de:"Ein weiterer großer Splitter von Standard Oil — Standard of California wurde 1984 zu Chevron und schluckte später Texaco und Gulf."}},lucent:{canonical:"lucent",category:"acquired",exitYear:2006,endState:{cn:"Nokia Bell Labs(经 Alcatel-Lucent 2006 + Nokia 2016 两轮并购)",tw:"Nokia Bell Labs(經 Alcatel-Lucent 2006 + Nokia 2016 兩輪併購)",en:"Nokia Bell Labs (via Alcatel-Lucent 2006 + Nokia 2016)",ja:"ノキア・ベル研究所（Alcatel-Lucent 2006、Nokia 2016 の二度の買収を経て）",es:"Nokia Bell Labs (vía Alcatel-Lucent en 2006 y Nokia en 2016)",ko:"노키아 벨연구소(알카텔-루슨트 2006, 노키아 2016 두 차례 인수를 거쳐)",fr:"Nokia Bell Labs (via Alcatel-Lucent en 2006 puis Nokia en 2016)",de:"Nokia Bell Labs (über Alcatel-Lucent 2006 und Nokia 2016)"},line:{cn:"1996 从 AT&T 拆分独立——含 Bell Labs。互联网泡沫破裂后做不下去,经两轮并购沉到芬兰 Nokia 旗下。",tw:"1996 從 AT&T 拆分獨立——含 Bell Labs。網路泡沫破裂後做不下去,經兩輪併購沉到芬蘭 Nokia 旗下。",en:"Spun out of AT&T in 1996 with Bell Labs in tow. Couldn't survive the dot-com bust; two acquisitions later it sits inside Finland's Nokia.",ja:"1996 年にベル研究所ごと AT&T から独立。ドットコム崩壊を生き延びられず、二度の買収を経てフィンランドのノキアの内側に沈んだ。",es:"Escindida de AT&T en 1996 con Bell Labs a cuestas. No sobrevivió al pinchazo puntocom; dos adquisiciones después reside dentro de la finlandesa Nokia.",ko:"1996년 벨연구소를 안고 AT&T에서 분사했다. 닷컴 붕괴를 버티지 못했고, 두 차례 인수를 거쳐 핀란드 노키아 안으로 가라앉았다.",fr:"Détachée d'AT&T en 1996 avec les Bell Labs. N'a pas survécu à l'éclatement de la bulle Internet ; deux rachats plus tard, elle loge chez le finlandais Nokia.",de:"1996 samt Bell Labs aus AT&T ausgegliedert. Überlebte das Platzen der Dotcom-Blase nicht; zwei Übernahmen später sitzt sie im finnischen Nokia."}},amoco:{canonical:"amoco",category:"acquired",exitYear:1998,endState:{cn:"BP 一部分(1998 BP–Amoco 合并)",tw:"BP 一部分(1998 BP–Amoco 合併)",en:"Folded into BP (BP–Amoco merger, 1998)",ja:"BP の一部（1998 年の BP・アモコ合併）",es:"Integrada en BP (fusión BP–Amoco, 1998)",ko:"BP의 일부(1998년 BP–아모코 합병)",fr:"Intégrée à BP (fusion BP–Amoco, 1998)",de:"Teil von BP (Fusion BP–Amoco, 1998)"},line:{cn:"标准石油印第安纳分支——1998 与英国石油合并,变成 BP Amoco 后简称 BP。",tw:"標準石油印第安納分支——1998 與英國石油合併,變成 BP Amoco 後簡稱 BP。",en:"Standard Oil of Indiana — merged with British Petroleum in 1998 to form BP Amoco, soon shortened to BP.",ja:"スタンダード・オイル・オブ・インディアナ——1998 年にブリティッシュ・ペトロリアムと合併して BP アモコとなり、まもなく BP に短縮された。",es:"La Standard Oil de Indiana: se fusionó con British Petroleum en 1998 para formar BP Amoco, pronto abreviado a BP.",ko:"인디애나 스탠더드 오일 — 1998년 브리티시 페트롤리엄과 합병해 BP 아모코가 되었고, 곧 BP로 줄었다.",fr:"La Standard Oil de l'Indiana — fusionnée avec British Petroleum en 1998 pour former BP Amoco, vite raccourci en BP.",de:"Standard Oil of Indiana — 1998 mit British Petroleum zu BP Amoco fusioniert, bald zu BP verkürzt."}},csco:{canonical:"csco",category:"listed",endState:{cn:"Cisco Systems(企业网络设备龙头,股价 24 年没回到 2000 年高点)",tw:"Cisco Systems(企業網路設備龍頭,股價 24 年沒回到 2000 年高點)",en:"Cisco Systems (enterprise networking leader; the stock has not reclaimed its March 2000 peak in 24 years)",ja:"シスコシステムズ（企業ネットワークの首位。株価は 24 年たっても 2000 年 3 月の高値に戻っていない）",es:"Cisco Systems (líder en redes corporativas; la acción no ha recuperado su máximo de marzo de 2000 en 24 años)",ko:"시스코 시스템즈(기업 네트워크 1위. 주가는 24년째 2000년 3월 고점을 회복하지 못했다)",fr:"Cisco Systems (leader du réseau d'entreprise ; le titre n'a pas retrouvé son sommet de mars 2000 en 24 ans)",de:"Cisco Systems (Marktführer im Unternehmensnetzwerk; die Aktie hat ihr Hoch vom März 2000 seit 24 Jahren nicht erreicht)"},line:{cn:"互联网泡沫顶时 SP500 #1,2024 年仍是企业网络龙头,但市值再没进过 Top 10。",tw:"網路泡沫頂時 SP500 #1,2024 年仍是企業網路龍頭,但市值再沒進過 Top 10。",en:"Held S&P 500 #1 at the dot-com peak; still the enterprise networking leader in 2024 — but never back in the Top 10.",ja:"ドットコムの頂点では S&P500 首位。2024 年もなお企業ネットワークの盟主だが、時価総額でトップ 10 に戻ることはなかった。",es:"Fue la número uno del S&P 500 en el pico puntocom; en 2024 sigue liderando las redes corporativas, pero nunca volvió al Top 10 por capitalización.",ko:"닷컴 정점에서 S&P 500 1위였다. 2024년에도 기업 네트워크의 선두지만, 시가총액으로는 다시 톱10에 들지 못했다.",fr:"Numéro un du S&P 500 au sommet de la bulle Internet ; toujours leader du réseau d'entreprise en 2024 — mais jamais revenue dans le Top 10.",de:"Beim Dotcom-Hoch die Nummer eins im S&P 500; 2024 weiter führend im Unternehmensnetzwerk — nach Marktwert aber nie zurück in den Top 10."}},intc:{canonical:"intc",category:"listed",endState:{cn:"Intel(x86 巨头,2020s 在 AI 周期落后)",tw:"Intel(x86 巨頭,2020s 在 AI 週期落後)",en:"Intel (x86 incumbent, lagging behind in the AI cycle)",ja:"インテル（x86 の巨人。2020 年代の AI サイクルでは後れを取っている）",es:"Intel (el titular del x86, rezagado en el ciclo de la IA)",ko:"인텔(x86의 강자, 2020년대 AI 사이클에서는 뒤처졌다)",fr:"Intel (l'établi du x86, à la traîne dans le cycle de l'IA)",de:"Intel (der x86-Platzhirsch, im KI-Zyklus zurückgefallen)"},line:{cn:"PC 时代的处理器垄断,2020s 让 Nvidia / TSMC / AMD 在 AI 周期里依次超车。",tw:"PC 時代的處理器壟斷,2020s 讓 Nvidia / TSMC / AMD 在 AI 週期裡依次超車。",en:"Processor monopoly of the PC era; passed in succession by Nvidia, TSMC, and AMD through the AI cycle.",ja:"PC 時代のプロセッサ独占。AI サイクルのなかでエヌビディア、TSMC、AMD に次々と抜かれた。",es:"El monopolio del procesador en la era del PC; adelantada sucesivamente por Nvidia, TSMC y AMD en el ciclo de la IA.",ko:"PC 시대 프로세서 독점 기업. AI 사이클을 지나며 엔비디아와 TSMC, AMD에 차례로 추월당했다.",fr:"Le monopole du processeur à l'ère du PC ; dépassée tour à tour par Nvidia, TSMC et AMD au fil du cycle IA.",de:"Das Prozessormonopol der PC-Ära; im KI-Zyklus nacheinander von Nvidia, TSMC und AMD überholt."}}},a={crown:{cn:"仍在 Top 10",tw:"仍在 Top 10",en:"Still on the Top 10",ja:"いまもトップ 10",es:"Sigue en el Top 10",ko:"여전히 톱10",fr:"Toujours dans le Top 10",de:"Weiter in den Top 10"},listed:{cn:"仍上市,已退出 Top 10",tw:"仍上市,已退出 Top 10",en:"Listed, no longer Top 10",ja:"上場継続、トップ 10 からは脱落",es:"Cotiza, fuera del Top 10",ko:"상장 유지, 톱10 이탈",fr:"Cotée, sortie du Top 10",de:"Notiert, aus den Top 10 gefallen"},split:{cn:"拆分",tw:"拆分",en:"Broken up",ja:"分割",es:"Desmembrada",ko:"분할",fr:"Démantelée",de:"Zerschlagen"},acquired:{cn:"被并购",tw:"被併購",en:"Acquired",ja:"買収",es:"Adquirida",ko:"피인수",fr:"Rachetée",de:"Übernommen"},bankrupt:{cn:"破产",tw:"破產",en:"Bankrupt",ja:"破綻",es:"Quebrada",ko:"파산",fr:"En faillite",de:"Insolvent"},lingering:{cn:"残存",tw:"殘存",en:"Lingering",ja:"残存",es:"Superviviente menguada",ko:"잔존",fr:"Survivance",de:"Rest"}},n={crown:"#006967",listed:"#5C7548",split:"#7A6F4F",acquired:"#A37736",bankrupt:"#A0292A",lingering:"#6B4E71"};export{a,e,n};
